package view;
import controller.StudentController; import model.*; import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*;
public class StudentView extends DashboardView {
 private final StudentController controller; private final Student student; private final Runnable logout;
 public StudentView(StudentController c,Student s,Runnable logout){super("Student",s.getName());controller=c;student=s;this.logout=logout;buildPages();setVisible(true);} protected void onLogout(){logout.run();}
 protected void buildNavigation(JPanel side){addNav(side,"Overview","Dashboard");addNav(side,"My details","Details");addNav(side,"Attendance","Attendance");addNav(side,"Marks & grades","Marks");}
 private void buildPages(){JPanel home=page("Welcome, "+student.getName(),"Here is your academic information.");JPanel stats=new JPanel(new GridLayout(1,2,14,0));stats.setOpaque(false);stats.add(stat("Student ID",String.valueOf(student.getStudentId())));stats.add(stat("Attendance",String.format("%.1f%%",student.getAttendance())));home.add(stats,BorderLayout.CENTER);addPage("Dashboard",home);
 JPanel details=page("My details","Your registered student information.");JPanel d=cardPanel();d.setLayout(new GridLayout(0,2,12,18));addDetail(d,"Student ID",String.valueOf(student.getStudentId()));addDetail(d,"Full name",student.getName());addDetail(d,"Username",student.getUsername());addDetail(d,"Class",student.getClassName());details.add(d,BorderLayout.CENTER);addPage("Details",details);
 JPanel attendance=page("My attendance","Your current attendance summary.");JPanel a=cardPanel();Attendance record=controller.getAttendance(student.getStudentId());String total=record==null?"0":String.valueOf(record.getTotalClasses());String attended=record==null?"0":String.valueOf(record.getAttendedClasses());String pct=record==null?"0.00%":String.format("%.2f%%",record.getAttendancePercentage());a.setLayout(new GridLayout(1,3,12,12));a.add(stat("Total classes",total));a.add(stat("Classes attended",attended));a.add(stat("Attendance",pct));attendance.add(a,BorderLayout.CENTER);addPage("Attendance",attendance);
 JPanel marks=page("Marks & grades","Your subject-wise academic performance.");String[] cols={"Subject","Marks","Grade"};DefaultTableModel m=new DefaultTableModel(cols,0);for(Marks x:controller.getMarks(student.getStudentId()))m.addRow(new Object[]{x.getSubject(),x.getMarks(),x.getGrade()});JPanel b=cardPanel();b.add(new JScrollPane(new JTable(m)),BorderLayout.CENTER);marks.add(b,BorderLayout.CENTER);addPage("Marks",marks);}
 private JPanel stat(String label,String value){JPanel p=cardPanel();p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel l=new JLabel(label);l.setForeground(new Color(105,116,135));JLabel v=new JLabel(value);v.setFont(new Font("SansSerif",Font.BOLD,26));v.setForeground(new Color(35,75,135));p.add(l);p.add(Box.createVerticalStrut(10));p.add(v);return p;}
 private void addDetail(JPanel p,String k,String v){JPanel x=new JPanel(new BorderLayout(0,5));x.setOpaque(false);JLabel a=new JLabel(k);a.setForeground(new Color(105,116,135));JLabel b=new JLabel(v);b.setFont(new Font("SansSerif",Font.BOLD,15));x.add(a,BorderLayout.NORTH);x.add(b,BorderLayout.CENTER);p.add(x);}
}
